import { ConvexError, v } from "convex/values";
import { mutation, query } from "./_generated/server";
import { assertAdmin, clamp, sha256Hex } from "./lib";

const DAY = 86_400_000;

/* ------------------------------------------------------------------- admin */

/**
 * Creates a one-time review link for a guest who has completed a stay. The raw token is
 * generated by the server and shown to the admin once; only its hash is stored here.
 */
export const createInvite = mutation({
  args: {
    secret: v.string(),
    token: v.string(),
    propertySlug: v.string(),
    unit: v.string(),
    nights: v.number(),
    stayed: v.string(),
    guestName: v.optional(v.string()),
  },
  handler: async (ctx, a) => {
    assertAdmin(a.secret);
    if (a.token.length < 24) throw new ConvexError("Invalid token.");
    const property = await ctx.db
      .query("properties")
      .withIndex("by_slug", (q) => q.eq("slug", a.propertySlug))
      .unique();
    if (!property) throw new ConvexError("Property not found.");
    await ctx.db.insert("reviewInvites", {
      tokenHash: await sha256Hex(a.token),
      propertySlug: a.propertySlug,
      unit: a.unit,
      nights: Math.max(1, Math.round(a.nights)),
      stayed: clamp(a.stayed, 40),
      guestName: a.guestName ? clamp(a.guestName, 60) : undefined,
      used: false,
      expiresAt: Date.now() + 45 * DAY,
      createdAt: Date.now(),
    });
  },
});

export const adminList = query({
  args: { secret: v.string() },
  handler: async (ctx, { secret }) => {
    assertAdmin(secret);
    const reviews = await ctx.db.query("reviews").collect();
    const invites = await ctx.db.query("reviewInvites").collect();
    return {
      reviews: reviews.sort((a, b) => b.createdAt - a.createdAt),
      invites: invites
        .filter((i) => !i.used && i.expiresAt > Date.now())
        .map((i) => ({
          id: i._id,
          propertySlug: i.propertySlug,
          unit: i.unit,
          stayed: i.stayed,
          guestName: i.guestName,
          expiresAt: i.expiresAt,
        })),
    };
  },
});

export const setStatus = mutation({
  args: {
    secret: v.string(),
    id: v.id("reviews"),
    status: v.union(v.literal("pending"), v.literal("published"), v.literal("hidden")),
  },
  handler: async (ctx, { secret, id, status }) => {
    assertAdmin(secret);
    await ctx.db.patch(id, { status });
  },
});

export const remove = mutation({
  args: { secret: v.string(), id: v.id("reviews") },
  handler: async (ctx, { secret, id }) => {
    assertAdmin(secret);
    await ctx.db.delete(id);
  },
});

export const revokeInvite = mutation({
  args: { secret: v.string(), id: v.id("reviewInvites") },
  handler: async (ctx, { secret, id }) => {
    assertAdmin(secret);
    await ctx.db.delete(id);
  },
});

/* ------------------------------------------------------------------ public */

/** For the guest's review page: what the link is for, without revealing anything else. */
export const inviteInfo = query({
  args: { token: v.string() },
  handler: async (ctx, { token }) => {
    if (token.length < 24 || token.length > 200) return null;
    const tokenHash = await sha256Hex(token);
    const invite = await ctx.db
      .query("reviewInvites")
      .withIndex("by_token", (q) => q.eq("tokenHash", tokenHash))
      .unique();
    if (!invite || invite.used || invite.expiresAt < Date.now()) return null;
    const property = await ctx.db
      .query("properties")
      .withIndex("by_slug", (q) => q.eq("slug", invite.propertySlug))
      .unique();
    if (!property) return null;
    const unit = property.units.find((u) => u.id === invite.unit);
    return {
      propertyTitle: property.title,
      unitLabel: unit?.label ?? "",
      stayed: invite.stayed,
      nights: invite.nights,
      guestName: invite.guestName ?? "",
    };
  },
});

/** A guest submits their review with the one-time token. It waits for approval before it shows. */
export const submit = mutation({
  args: { token: v.string(), author: v.string(), quote: v.string() },
  handler: async (ctx, { token, author, quote }) => {
    if (token.length < 24 || token.length > 200) throw new ConvexError("This review link isn't valid.");
    const tokenHash = await sha256Hex(token);
    const invite = await ctx.db
      .query("reviewInvites")
      .withIndex("by_token", (q) => q.eq("tokenHash", tokenHash))
      .unique();
    if (!invite || invite.used || invite.expiresAt < Date.now()) {
      throw new ConvexError("This review link has already been used or has expired.");
    }
    const name = clamp(author, 60);
    const text = clamp(quote, 600);
    if (name.length < 2) throw new ConvexError("Please enter your name.");
    if (text.length < 10) throw new ConvexError("Please write a little more about your stay.");

    await ctx.db.insert("reviews", {
      propertySlug: invite.propertySlug,
      unit: invite.unit,
      author: name,
      stayed: invite.stayed,
      nights: invite.nights,
      quote: text,
      status: "pending",
      createdAt: Date.now(),
    });
    await ctx.db.patch(invite._id, { used: true });
  },
});
